	export type BuildArgs = [...children: AdmitBound<T.Term[], T.AdmittedNodes>];
	export type LooseArgs = [...children: LooseValue<T.Term, T.LeafScalarMap, T.LeafStringMap, T.NamespaceMap>[]];
